import { client, streams } from "@trigger.dev/sdk";
import { agentTask } from "./src/trigger/agent";

async function main() {
  // Initialize the client
  const trigger = client();

  // Trigger the agent task with a city
  const run = await trigger.sendEvent({
    name: "agent.trigger",
    id: agentTask.id,
    payload: {
      city: "Paris",
    },
  });

  console.log(`Run started...`);

  // Subscribe to the ai-output stream
  const aiStream = streams.read(run.id, "ai-output");

  // Print each chunk as it arrives
  for await (const chunk of aiStream) {
    console.log(chunk);
  }

  // Print the Run ID at the end
  console.log(`Run ID: ${run.id}`);
}

main().catch(console.error);

